std::shared_ptr<::cw::data::CWPyElement> parse_summary_xml(
    const ::cw::lib::String& path, std::optional<::cw::lib::Bytes> bytes = std::nullopt)
{
    // C++ の並行処理への対応として、データベース用の Summary は実行中
    // のシナリオから独立させる。 Python の GIL なしで CWPy の変
    // 更可能なシナリオ・キャッシュを読む代わりに、 xml2element の共
    // 通パーサーを直接使い、文書全体・バイト列・Storage の扱いを揃える。
    ::cw::data::SimpleXmlParser parser;
    parser.initialize(path, "", bytes ? std::optional<::cw::lib::Value>(*bytes)
                                      : std::nullopt, false, std::nullopt);
    return parser.parse();
}

