::cw::lib::Value column_value(const ::cw::lib::sqlite::Column& column)
{
    switch (column.type()) {
    case ::cw::lib::sqlite::ColumnType::Null: return {};
    case ::cw::lib::sqlite::ColumnType::Integer: return ::cw::lib::Value(column.as_integer());
    case ::cw::lib::sqlite::ColumnType::Real: {
        const auto value = column.as_real();
        // SQLite は通常 NaN/Inf を保存できないが、拡張や不
        // 正な旧データベースから型付きラッパーへ届く場合がある。 Python
        // と同じ NULL 相当の不正データ境界を維持し、有限でない値
        // を ScenarioHeader・キャッシュの比較へ入れない。
        return std::isfinite(value) ? ::cw::lib::Value(value) : ::cw::lib::Value{};
    }
    case ::cw::lib::sqlite::ColumnType::Text: return ::cw::lib::Value(column.as_text());
    case ::cw::lib::sqlite::ColumnType::Blob: return ::cw::lib::Value(column.as_blob());
    }
    return {};
}

::cw::lib::Value db_record_value(const ::cw::lib::sqlite::Row& row)
{
    auto record = std::make_shared<::cw::header::DbRecord>();
    const auto& names = row.column_names();
    for (std::size_t i = 0; i < names.size(); ++i) record->fields[names[i]] = column_value(row.at(i));
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(record));
}

std::vector<std::map<::cw::lib::String, ::cw::lib::Value>>
db_image_rows(SqliteConnection& db, const ::cw::lib::String& dpath, const ::cw::lib::String& fname)
{
    const auto result = db.execute(
        "SELECT scale,image,imgpath,postype,numorder FROM scenarioimage "
        "WHERE dpath=? AND fname=? ORDER BY numorder",
        {SqliteBind(dpath), SqliteBind(fname)});
    std::vector<std::map<::cw::lib::String, ::cw::lib::Value>> rows;
    rows.reserve(result.size());
    for (const auto& row : result) {
        std::map<::cw::lib::String, ::cw::lib::Value> values;
        for (std::size_t i = 0; i < row.column_names().size(); ++i)
            values[row.column_names()[i]] = column_value(row.at(i));
        rows.push_back(std::move(values));
    }
    return rows;
}

bool has_column(const std::vector<::cw::lib::sqlite::ColumnInfo>& columns, const char* name)
{
    return std::any_of(columns.begin(), columns.end(), [name](const auto& column) { return column.name == name; });
}

bool has_primary_key_column(const std::vector<::cw::lib::sqlite::ColumnInfo>& columns, const char* name)
{
    return std::any_of(columns.begin(), columns.end(), [name](const auto& column) {
        return column.name == name && column.primary_key;
    });
}

void rebuild_scenarioimage(SqliteConnection& db, bool had_scale)
{
    exec_sql(db, "CREATE TABLE scenarioimage_temp (dpath TEXT,fname TEXT,numorder INTEGER,"
                 "scale INTEGER,image BLOB,imgpath TEXT,postype TEXT,"
                 "PRIMARY KEY(dpath,fname,numorder,scale))");
    exec_sql(db, had_scale
        ? "INSERT OR REPLACE INTO scenarioimage_temp(dpath,fname,numorder,scale,image,imgpath,postype) "
          "SELECT dpath,fname,numorder,COALESCE(scale,1),image,imgpath,postype FROM scenarioimage"
        : "INSERT OR REPLACE INTO scenarioimage_temp(dpath,fname,numorder,scale,image,imgpath,postype) "
          "SELECT dpath,fname,numorder,1,image,imgpath,postype FROM scenarioimage");
    exec_sql(db, "DROP TABLE scenarioimage");
    exec_sql(db, "ALTER TABLE scenarioimage_temp RENAME TO scenarioimage");
}

void migrate_schema(SqliteConnection& db)
{
    db.begin("IMMEDIATE");
    try {
        auto scenario_columns = db.table_columns("scenariodb");
        if (scenario_columns.empty()) {
            exec_sql(db,
                "CREATE TABLE scenariodb ("
                "dpath TEXT,type INTEGER,fname TEXT,name TEXT,author TEXT,desc TEXT,"
                "skintype TEXT,levelmin INTEGER,levelmax INTEGER,coupons TEXT,"
                "couponsnum INTEGER,startid INTEGER,tags TEXT,ctime INTEGER,mtime INTEGER,"
                "image BLOB,imgpath TEXT,wsnversion TEXT,PRIMARY KEY(dpath,fname))");
            scenario_columns = db.table_columns("scenariodb");
        }
        if (!has_column(scenario_columns, "type")) {
            exec_sql(db, "ALTER TABLE scenariodb ADD COLUMN type INTEGER");
            exec_sql(db, "UPDATE scenariodb SET type=?", {SqliteBind(static_cast<::cw::lib::Integer>(0))});
        }
        if (!has_column(scenario_columns, "imgpath")) exec_sql(db, "ALTER TABLE scenariodb ADD COLUMN imgpath TEXT");
        if (!has_column(scenario_columns, "wsnversion")) exec_sql(db, "ALTER TABLE scenariodb ADD COLUMN wsnversion TEXT");
        if (db.execute("PRAGMA index_info('scenariodb_index1')").empty())
            exec_sql(db, "CREATE INDEX scenariodb_index1 ON scenariodb(dpath)");

        auto type_columns = db.table_columns("scenariotype");
        if (type_columns.empty()) {
            exec_sql(db, "CREATE TABLE scenariotype (dpath TEXT,fname TEXT,skintype TEXT,"
                       "PRIMARY KEY(dpath,fname,skintype))");
            exec_sql(db, "CREATE INDEX IF NOT EXISTS scenariotype_index1 ON scenariodb(dpath,fname)");
        }

        auto image_columns = db.table_columns("scenarioimage");
        if (image_columns.empty()) {
            exec_sql(db, "CREATE TABLE scenarioimage (dpath TEXT,fname TEXT,numorder INTEGER,"
                       "scale INTEGER,image BLOB,imgpath TEXT,postype TEXT,"
                       "PRIMARY KEY(dpath,fname,numorder,scale))");
        } else {
            if (!has_column(image_columns, "postype")) exec_sql(db, "ALTER TABLE scenarioimage ADD COLUMN postype TEXT");
            if (!has_column(image_columns, "imgpath")) exec_sql(db, "ALTER TABLE scenarioimage ADD COLUMN imgpath TEXT");
            // Py は scale 列がない場合だけ scenarioimage
            // を再構築する。 ネイティブ版では、scale 列があっても主キーに含
            // まれない旧共有データベースもキーを作り直し、倍率ごとの行を保持する。
            const bool had_scale = has_column(image_columns, "scale");
            if (!had_scale || !has_primary_key_column(image_columns, "scale"))
                rebuild_scenarioimage(db, had_scale);
        }
        db.commit();
    } catch (...) {
        try { db.rollback(); } catch (...) {}
        throw;
    }
}

std::shared_ptr<::cw::header::ScenarioHeader>
header_from_db_row(SqliteConnection& db, const ::cw::lib::sqlite::Row& row,
                   const ::cw::lib::String& skintype, bool update)
{
    auto record = db_record_value(row);
    const auto* dpath = row.column_names().empty() ? nullptr : &row.at("dpath");
    const auto* fname = row.column_names().empty() ? nullptr : &row.at("fname");
    std::optional<std::vector<std::map<::cw::lib::String, ::cw::lib::Value>>> images;
    if (dpath && fname && dpath->type() == ::cw::lib::sqlite::ColumnType::Text &&
        fname->type() == ::cw::lib::sqlite::ColumnType::Text &&
        row.at("image").is_null()) {
        images = db_image_rows(db, dpath->as_text(), fname->as_text());
    }
    auto header = std::make_shared<::cw::header::ScenarioHeader>();
    header->initialize(std::move(record), std::move(images));
    (void)skintype;
    (void)update;
    // 古い行の更新・削除は再追加できる Scenariodb::create_header
    // が行う。 このヘルパーは SQLite の行をオブジェクト化するだけとする。
    return header;
}

std::filesystem::path resolve_path(const std::filesystem::path& p) {
    if (::cardwirth::platform::is_mounted_user_path(p)) return p.lexically_normal();
    std::error_code ec;
    auto result = std::filesystem::weakly_canonical(p, ec);
    return ec ? p : result;
}

std::optional<::cw::lib::Bytes> read_file(const std::filesystem::path& p) {
    if (::cardwirth::platform::is_mounted_user_path(p)) {
        const auto mounted = ::cardwirth::platform::read_mounted_user_file(p);
        if (!mounted) return std::nullopt;
        ::cw::lib::Bytes result;
        result.reserve(mounted->size());
        for (const auto value : *mounted)
            result.push_back(std::to_integer<std::uint8_t>(value));
        return result;
    }
    std::ifstream in(p, std::ios::binary);
    if (!in) return std::nullopt;
    return ::cw::lib::Bytes(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
}

::cw::lib::String value_string(const ::cw::lib::Value& value) {
    if (const auto* s = std::get_if<::cw::lib::String>(&value.storage())) return *s;
    if (const auto* decimal = std::get_if<::cw::lib::Decimal>(&value.storage())) return decimal->to_string(true);
    if (const auto* i = std::get_if<::cw::lib::Integer>(&value.storage())) return std::to_string(*i);
    if (const auto* r = std::get_if<::cw::lib::Real>(&value.storage())) {
        if (!std::isfinite(*r)) return {};
        std::ostringstream text;
        text << std::setprecision(std::numeric_limits<::cw::lib::Real>::max_digits10) << *r;
        return text.str();
    }
    if (const auto* b = std::get_if<bool>(&value.storage())) return *b ? "True" : "False";
    return {};
}

